// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // The reference must initialize with msg.sender via the proxy initializer.
        // We deploy a fresh instance in setUp, so the initializing call sets owner to address(this).
        // The fuzzed 'actor' is irrelevant to the owner() return value because the contract is already initialized.
        // However, the property must hold universally: owner() returns the non-zero address that was set during initialization.
        // The mutant returns address(0), so the assertion that owner() != address(0) passes on the reference and fails on the buggy version.
        assertTrue(c.owner() != address(0));
    }
}

