// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(address initialOwner) public {
        // 1. ADMISSIBLE domain: initialOwner != address(0) (Ownable ctor rejects zero owner)
        vm.assume(initialOwner != address(0));

        // 2. Drive initialization
        vm.prank(address(0x123)); // prank to any nonzero address; initializer sets owner to msg.sender
        c.initialize(
            1, // credChainId_
            1, // credId_
            "verification",
            address(0xdead) // protocolFeeDestination_
        );

        // 3. The universal property: owner() returns msg.sender of the initializer (the address that deployed/initialized),
        //    which must be a nonzero address. The mutant always returns address(0).
        assertTrue(c.owner() != address(0));
    }
}

