// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize(1, 1, "test", address(this));
    }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address storedOwner = c.owner();
        vm.prank(caller);
        address reportedOwner = c.owner();
        assertTrue(reportedOwner == storedOwner, "owner must be independent of msg.sender");
    }
}
